    &mut self,
    run_id: &str,
    context: Option<String>,
    images: Vec<Vec<u8>>,
) -> Result<(), String> {
    let run = self.host.run(run_id).map_err(|error| error.to_string())?.clone();
    let runtime = self
        .native_agent_runtime
        .as_mut()
        .ok_or_else(|| "Native AgentRuntime is not initialized.".to_owned())?;
